#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# learnvedicmath.com owner setup. The written guide with every click path is
# docs/owner-setup-learnvedicmath.md; this wizard follows it in the same order.
# Run from the repo root, signed in with gh:  bash docs/tools/setup-learnvedicmath.sh
# Public values are saved outside the repo in ~/.config/learnvedicmath/setup.env
# (mode 600). The one secret (the Cloudflare API token) goes only into GitHub via
# gh secret set; it is never written to a file and never shown on screen.

run_wizard() {

ENV_FILE="${ENV_FILE:-$HOME/.config/learnvedicmath/setup.env}"
mkdir -p "$(dirname "$ENV_FILE")"
GUIDE="docs/owner-setup-learnvedicmath.md"

TOTAL_STAGES=15

banner "learnvedicmath.com: owner setup"

stage "Passkeys or security keys on every account"
say "Before anything else, protect the accounts that control the site."
note "Guide: $GUIDE section 1. Register two keys per account; never SMS."
open_url "https://github.com/settings/security"
step "GitHub: Passkeys > Add a passkey, and Security keys > Register new security key."
pause "Done with GitHub? Press Enter"
open_url "https://myaccount.google.com/security"
step "Google (the account that will own Firebase): Passkeys and security keys > Create a passkey."
pause "Done with Google? Press Enter"
open_url "https://account.squarespace.com/settings/security"
step "Squarespace: Two-factor authentication (security keys if offered, else an authenticator app)."
step "Then Domains > learnvedicmath.com: keep Domain lock and Auto-renew on."
pause "Done with Squarespace? Press Enter"

stage "Cloudflare account and the learnvedicmath.com zone"
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up, then at once: avatar > My Profile > Authentication > add your security keys."
step "Home > Add a domain > learnvedicmath.com > Free plan."
step "In the DNS review, delete the A records to 198.49.23.144/145 and 198.185.159.144/145,"
step "and a www CNAME to ext-cust.squarespace.com if present."
ask CF_NAMESERVERS "Paste the two Cloudflare nameservers, separated by a space:"
write_env CF_NAMESERVERS "$CF_NAMESERVERS"

stage "Nameservers at Squarespace"
open_url "https://account.squarespace.com/domains"
step "learnvedicmath.com > DNS > DNSSEC: make sure it is OFF before changing nameservers."
step "DNS > Domain nameservers > Use custom nameservers > enter: $CF_NAMESERVERS > Save."
note "Cloudflare emails you when the zone is Active (minutes to hours)."
if command -v dig >/dev/null 2>&1; then
  note "Right now dig says: $(dig NS learnvedicmath.com +short 2>/dev/null | tr '\n' ' ')"
fi
pause "Press Enter once Cloudflare shows the zone as Active (re-run later if not yet)"

stage "DNSSEC"
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/dns/settings"
step "DNSSEC > Enable DNSSEC. Keep the DS values (key tag, algorithm 13, digest type 2, digest) on screen."
open_url "https://account.squarespace.com/domains"
step "learnvedicmath.com > DNS > DNSSEC > add the DS record with exactly those values."
note "Check tomorrow: Cloudflare says Success, and https://dnsviz.net/d/learnvedicmath.com/dnssec/ is all green."
pause

stage "Email Routing: privacy@, hello@, security@"
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/email/routing/overview"
step "Get started > Destination addresses > add your Gmail > confirm the email Cloudflare sends."
step "Custom addresses: privacy, hello and security, each to your Gmail."
step "Click 'Add records and enable'."
step "Send a test mail to each address from another account and check it arrives."
pause "All three arrive? Press Enter"

stage "DMARC and CAA"
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/email/dmarc-management"
step "DMARC Management > Enable, then set the _dmarc TXT record to:"
say "v=DMARC1; p=reject; sp=reject; adkim=s; aspf=s; rua=mailto:<the address Cloudflare gave>"
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/dns/records"
step "Add three CAA records on @ (flags 0):"
say "issue letsencrypt.org  |  issue pki.goog  |  iodef mailto:security@learnvedicmath.com"
pause

stage "Verify the domain in GitHub"
open_url "https://github.com/settings/pages"
step "Verified domains > Add a domain > learnvedicmath.com. GitHub shows a TXT record."
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/dns/records"
step "Add TXT with name _github-pages-challenge-sbmadhav (ONLY that part) and GitHub's value."
step "Back in GitHub: Verify."
pause "Shows Verified? Press Enter"

stage "Cloudflare API token for GitHub Actions"
say "This makes the one secret CI needs. It goes straight into GitHub, nowhere else."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token > Create Custom Token > name github-actions-learnvedicmath"
step "Permissions: Account Workers Scripts Edit; Account Account Settings Read;"
step "Zone Workers Routes Edit; Zone Zone Read; User User Details Read; User Memberships Read."
step "Account resources: your account. Zone resources: Specific zone > learnvedicmath.com."
step "No IP filtering. TTL: today to one year from today (add a calendar reminder)."
step "Create Token. Copy it (Cloudflare shows it once)."
warn "Paste it only here (hidden input), never into a chat."
ask_secret CLOUDFLARE_API_TOKEN "Paste the token:"
if confirm "Has the production environment been created yet (guide section 15)?"; then
  if command -v gh >/dev/null 2>&1 && printf '%s' "$CLOUDFLARE_API_TOKEN" | gh secret set CLOUDFLARE_API_TOKEN --env production >/dev/null 2>&1; then
    WRITTEN_SECRET+=("CLOUDFLARE_API_TOKEN (env production)")
    printf '  %s✓ set%s GitHub environment secret CLOUDFLARE_API_TOKEN\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("GitHub secret CLOUDFLARE_API_TOKEN (gh secret set CLOUDFLARE_API_TOKEN --env production)")
    warn "could not set the environment secret; set it later by hand"
  fi
else
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
fi
CLOUDFLARE_API_TOKEN=""

stage "Cloudflare account id"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Workers & Pages > Overview > right side > Account ID > copy (it is public)."
ask CLOUDFLARE_ACCOUNT_ID "Paste the account id:"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
set_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"

stage "Zone settings: HTTPS, www redirect, rate limit"
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/ssl-tls/edge-certificates"
step "Always Use HTTPS: on. Minimum TLS Version: 1.2. (HSTS here stays off.)"
open_url "https://dash.cloudflare.com/?to=/:account/learnvedicmath.com/rules"
step "Redirect Rules > Create > template 'Redirect from WWW to root' (301, keep query)."
step "Security > WAF > Rate limiting rules: /_csp and /import/, 20 per 10 s per IP, block 10 s."
step "Security > Bots: leave Bot Fight Mode OFF for now (task 15.7)."
step "Notifications: add SSL and DNSSEC alerts to your email."
pause

stage "Cloudflare Web Analytics"
open_url "https://dash.cloudflare.com/?to=/:account/web-analytics"
step "Add a site > learnvedicmath.com > choose the JavaScript snippet (NOT automatic setup)."
step "Copy the token inside data-cf-beacon (it is public)."
ask CF_WEB_ANALYTICS_TOKEN "Paste the Web Analytics token:"
write_env CF_WEB_ANALYTICS_TOKEN "$CF_WEB_ANALYTICS_TOKEN"

stage "New Firebase project"
open_url "https://console.firebase.google.com/"
step "Create a project: name Learn Vedic Math, id learnvedicmath (or learnvedicmath-prod)."
step "Google Analytics for this project: OFF."
step "If you said yes to the Blaze plan: Upgrade > Blaze, then a \$5 budget with 50/90/100% alerts:"
open_url "https://console.cloud.google.com/billing/budgets"
ask FIREBASE_PROJECT_ID "The project id you got:"
write_env FIREBASE_PROJECT_ID "$FIREBASE_PROJECT_ID"
note "When the builder says cloud/setup.sh is ready (task 8.4), run:"
say "bash cloud/setup.sh $FIREBASE_PROJECT_ID learnvedicmath.com www.learnvedicmath.com"
pause

stage "App Check key and API key restrictions"
open_url "https://console.cloud.google.com/security/recaptcha?project=$FIREBASE_PROJECT_ID"
step "Create key: Website, domains learnvedicmath.com and www.learnvedicmath.com, no checkbox."
ask APPCHECK_SITE_KEY "Paste the reCAPTCHA key id (public):"
write_env APPCHECK_SITE_KEY "$APPCHECK_SITE_KEY"
open_url "https://console.firebase.google.com/project/$FIREBASE_PROJECT_ID/appcheck"
step "Apps > your web app > reCAPTCHA Enterprise > paste the key > Save. Do NOT enforce yet."
open_url "https://console.cloud.google.com/apis/credentials?project=$FIREBASE_PROJECT_ID"
step "Browser key (auto created by Firebase) > Websites: https://learnvedicmath.com/*,"
step "https://www.learnvedicmath.com/*, http://localhost:*/*, http://127.0.0.1:*/*, https://$FIREBASE_PROJECT_ID.firebaseapp.com/*"
step "Restrict key to: Cloud Firestore, Identity Toolkit, Token Service, Firebase App Check, Firebase Installations."
warn "Never add *.workers.dev."
pause

stage "GoatCounter site code"
open_url "https://www.goatcounter.com/"
step "Sign in (the sbmadhav account) > Settings > Sites > add site code learnvedicmath."
step "In its settings: untick region and language; Ignore IPs: your home IP; Data retention: 395 days."
GOATCOUNTER_CODE="learnvedicmath"
ask GOATCOUNTER_CODE "Site code you created (Enter if learnvedicmath):"
[[ -z "$GOATCOUNTER_CODE" ]] && GOATCOUNTER_CODE="learnvedicmath"
write_env GOATCOUNTER_CODE "$GOATCOUNTER_CODE"

stage "Search Console, uptime and GitHub code security"
open_url "https://search.google.com/search-console"
step "Add property > Domain > learnvedicmath.com > add the TXT in Cloudflare > Verify."
step "Self-designate as child-directed for YouTube: https://support.google.com/youtube/answer/171780"
open_url "https://uptimerobot.com/"
step "Monitors (5 min, email): /, /play/ and /sw.js on https://learnvedicmath.com"
open_url "https://github.com/sbmadhav/vedic-math/settings/security_analysis"
step "Dependabot alerts and updates on; CodeQL > Default; secret scanning and push protection on."
step "Settings > Environments > production (branch main only), if not done yet."
pause "Press Enter to finish"

note "Give the builder these public values (also in $ENV_FILE):"
note "  Cloudflare account $CLOUDFLARE_ACCOUNT_ID, Web Analytics token, Firebase $FIREBASE_PROJECT_ID,"
note "  App Check key $APPCHECK_SITE_KEY, GoatCounter $GOATCOUNTER_CODE"
pause

finish
}

run_wizard "$@"; exit
